const re = new RegExp(PAT, 'gm');

function findall(log) {
  // emulate Python re.findall with one capturing group: return group 1s
  const out = [];
  let m;
  re.lastIndex = 0;
  while ((m = re.exec(log)) !== null) {
    out.push(m[1]);
    if (m[0].length === 0) re.lastIndex++;
  }
  return out;
}

